        { title: "Separate variables", math: t`\frac{du}{u^2 + 1} = dx` },
        { title: "Integrate both sides", math: t`\arctan(u) = x + C` },
        { title: "Back-substitute $u = x + y + 1$", math: t`\arctan(x + y + 1) = x + C` }
